from builtins import range
from builtins import object
import paramiko
from future import standard_library
from robot.libraries.BuiltIn import BuiltIn
from taf.ul.trs_e2e_fw.lib.utils.config_utils import get_config_variable
from taf.ul.trs_e2e_fw.lib.utils.logger.robotbackgroundlogger import BackgroundLogger
from taf.ul.trs_e2e_fw.lib.utils.string_format import decode_str

logger = BackgroundLogger.Instance()
standard_library.install_aliases()


class Isakmp(object):
    """Isakmp"""
    def __init__(self):
        self.store = {}
        self.ipstat_cmd = "sudo ipsec statusall"
        self.ipsec_restart_cmd = "sudo ipsec restart"
        self.ipsec_loglevel_cmd = "sudo ipsec stroke loglevel ike 4"
        # self.var_log_tail_cmd = "tail -f /var/log/messages | grep -i charon > /tmp/temp.txt"
        # var log
        # self.var_log_cat_cmd = "cat /tmp/temp.txt | grep -i charon"
        # self.ip_sec_v2_cmd = "cat /var/log/messages "  # "cat {0} > /.wireshark/ipsec_v2_table"
        self.ipstat_regx = r"IKEv2 SPIs:\s+(\w+)_i\**\s+(\w+)_r\**,\s+.+\n.*:\sIKE\sproposal:\s+(\w+)\/(\w+)"
        self.var_log_regx = ""

    def perform_isakmp_decryption(self, ipsec_gateway_section, bts_section, **kwargs):
        """
        Args:
            ipsec_gateway_section: section in test line config json file, under "ipsec_devices"
            section which contains the credentials of ipsec gw
            bts_section: section in test line config json file which contains the credentials of bts

        performs the following steps:
            1)get all tunnel details from ipstat cmd output on bts
                                ( initiator_spi, responders_spi, encryption_alg, integity_alg)
            2)ipstat op is used to find all tunnels' details (Sk_ai, Sk_ar, Sk_ei, Sk_er)
            3)validate all obtained details( not implimented yet)
            4)adding all the details wiresharks ipsec v2 table

        Returns: None

        """
        self.charon_logs_path = kwargs.get('charon_logs_path', '/var/log/syslog')
        self.charon_logs_grep_op_file = '/tmp/temp.txt'
        self._set_all_remote_connections(ipsec_gateway_section, bts_section)
        ip_stat_cmd_dets = self._get_details_from_ipstat_cmd()
        var_log_details = self._get_details_from_var_log(ip_stat_cmd_dets)
        self._validate_cmd_details_and_var_log(ip_stat_cmd_dets, var_log_details)
        self._add_var_log_details_to_ip_sec_v2_table(var_log_details)

    # ########################## get_details_from_ip_stat_cmd ##################################

    def _get_details_from_ipstat_cmd(self):
        """
        Args:
            ipsec_gateway_section: section in test line config json file which contains the
            credentials of ipsec gw
            bts_section: section in test line config json file which contains the credentials of bts

        performs the following steps in the given order:
            1)setting remote connection with ipsec gw and bts
            2)Execute var/log cmd & ipsec log level cmd on the bts
            3)Execute ipsec restart cmd on sec gw.
            4)Wait for some time(50 sec) and execute ipsec status cmd
            5)Get all the list of tunnel info strings from ipsec status cmd's O/P.
            6)Extract details from list of tunnel info string and store it as list of dictionary,
            each containing details of tunnels( initiator_spi, responders_spi, encryption_alg,
            integity_alg)

        Returns: list of dictionaries.Each dictionary containg details of tunnels( initiator_spi,
        responders_spi, encryption_alg, integity_alg ).

        """
        self._execute_all_setup_commands_on_bts_and_gw()
        command_result = self._get_output_from_command_execution(self.ipstat_cmd, "bts")  # bts
        tunnel_info_list = self._get_list_of_tunnel_info_strings_from_cmd_output(command_result)
        logger.debug("tunnel list :: \n{}".format(str(tunnel_info_list)))
        return self.get_details_from_list_of_tunnel_info(tunnel_info_list)

    def _set_all_remote_connections(self, ipsec_gateway_section, bts_section):
        """

        Args:
            ipsec_gateway_section:  section in test line config json file which contains the
            credentials of ipsec gw
            bts_section: section in test line config json file which contains the credentials of
            bts
        Function performs the follwing steps:
            1)Establishes a ssh connection with security gateway
            2)Establishes a ssh connection with bts

        Returns:None

        """
        host_details = get_config_variable(["ipsec_devices", ipsec_gateway_section])
        self._set_remote_connection_with_host(host_details, alias="ipsec")
        host_details = get_config_variable([bts_section])
        self._set_remote_connection_with_host(host_details, alias="bts")
        self._set_remote_connection_with_host(host_details, alias="bts_tail_check")

    def _execute_all_setup_commands_on_bts_and_gw(self):
        """
        Function performs the follwoing steps:
            1)Executes tail command for /var/log/messages on bts. output is redirected to a temp file.
            2)Executes a command to set log level on bts.
            3)Executes ipsec restart command on security gateway.
            4)sleep for 50sec to allow var/log/messages to get populated with required details or messages.

        Returns: None

        """
        self.var_log_tail_cmd = "tail -f {} | grep -i charon > {}".format(self.charon_logs_path,
                                                                          self.charon_logs_grep_op_file)  # var log
        self._get_output_from_command_execution(self.var_log_tail_cmd, "bts_tail_check", wait_for_read=False)
        self._get_output_from_command_execution(self.ipsec_loglevel_cmd, "bts")  # to be done on bts
        self._get_output_from_command_execution(self.ipsec_restart_cmd, "ipsec")  # to be done on sec gateway
        time.sleep(50)

    def _get_list_of_tunnel_info_strings_from_cmd_output(self, command_result):
        """

        Args:
            command_result: result of execution of  ipsec status cmd.

        Splits the string in command_result variable and returns a list of strings. Each string represents a tunnel.

        Returns: list of strings. Each string has information about a tunnel.

        """
        result = command_result.split("ESTABLISHED ")
        # logger.debug("result for ipsec statusall  :: \n" + str(result))
        return result

    def get_details_from_list_of_tunnel_info(self, tunnels_info_strings):
        """

        Args:
            tunnels_info_strings: list of strings. Each string has information about a tunnel.


        Each element of  list of tunnel info strings represents a tunnel and it contains many details about the tunnel.
        This function extracts only required  tunnel information from each element in the list.Function returns list of
        dictionaries.Each dictionary contains only required details of a tunnel
        ( initiator_spi, responders_spi, encryption_alg, integity_alg ).

        Returns: list of dictionaries.Each dictionary containg details of tunnels
        ( initiator_spi, responders_spi, encryption_alg, integrity_alg ).

        """
        tunnels_details = []
        tunnels = tunnels_info_strings[1:]
        for tunnel in tunnels:
            re_object = self._get_re_object_from_regx(self.ipstat_regx, tunnel)
            if re_object:
                tunnels_details.append(self._get_ipstat_details_from_regx_object(re_object))
        logger.debug("tunnel details :: \n{}".format(json.dumps(tunnels_details, sort_keys=True, indent=4)))
        return tunnels_details

    def _get_re_object_from_regx(self, reg_xpression, tunnel_info):
        """

        Args:
            reg_xpression:  pattern that is to be matched  with the tunnel info string.
            tunnel_info: String that contains the information about tunnel.

        Uses regular expression to extract required details from the tunnel string. It returns an RE object that
         contains all the required details about a tunnel

        Returns: RE object containing required details of a tunnel.


        """
        re_obj = re.search(reg_xpression, tunnel_info)
        logger.debug("re_obj " + str(re_obj))
        # if not re_obj:
        #     BuiltIn().fail("Error :: Could not fetch attributes for tunnel information\n{0}".format(tunnel_info))
        return re_obj

    def _get_ipstat_details_from_regx_object(self, re_object):
        """

        Args:
            re_object: object containing required details of a tunnel.

        Function extracts the required details from the RE object and puts into a dictionary.

        Returns: dictionary containing all the required details of a tunnel.
        ( initiator_spi, responders_spi, encryption_alg, integrity_alg ).

        """
        result = {
            "initiators_spi": re_object.group(1).strip(),
            "responders_spi": re_object.group(2).strip(),
            "encryption_alg": self._format_obtained_algorithm(re_object.group(3).strip(), "encryption_alg"),
            "integrity_alg": self._format_obtained_algorithm(re_object.group(4).strip(), "integrity_alg")
        }
        logger.debug("Attributes for tunnel " + str(result))
        return result

    def _format_obtained_algorithm(self, algorithm, algorithm_type):
        """

        Args:
            algorithm: encryption or integrity algorithm(string)
            algorithm_type: type of algorithm(string). Takes value either "encryption_alg" or "integrity_alg".

        Function used to format the algorithm.
        The format of ipsec statusall cmd obtained is not in suitable for wireshark decryption table. It is formatted so
          that it is suitable for wireshark decryption table.

        Returns: (string)Formatted algorithm name

        """
        if algorithm_type == "encryption_alg":
            return get_config_variable(["ipsec", "enc", algorithm])
        elif algorithm_type == "integrity_alg":
            return get_config_variable(["ipsec", "auth", algorithm])

    # ################# get_details_from_varlog_cmd #################

    def _get_details_from_var_log(self, ip_stat_cmd_dets):
        """

        Args:
            ipsec_gateway_section:  section in test line config json file which contains the credentials of ipsec gw.
            ip_stat_cmd_dets: tunnel information obtained from execution of ipsec status command.

        Function performs the following step:
            1)executes command to get contents of var/log dump stored in a temp file.
            2)terminates session with sec gw
            3)extracts other details of a tunnel (Sk_ai, Sk_ar, Sk_ei, Sk_er)

        Returns: list of dictionaries. Each dictionaries contains all the required details of a tunnel.
        ( initiator_spi, responders_spi, encryption_alg, integity_alg, Sk_ai, Sk_ar, Sk_ei, Sk_er )

        """
        command_result = self._get_journal_output()  # var/log bts
        # command_result = self._get_output_from_file("/home/ute/test.txt")
        self._terminate_remote_connection_with_host(alias="ipsec")
        self._terminate_remote_connection_with_host(alias="bts")
        self._terminate_remote_connection_with_host(alias="bts_tail_check")
        return self._get_var_log_details_from_cmd(command_result, ip_stat_cmd_dets)

    def _get_var_log_details_from_cmd(self, command_result, ip_stat_cmd_dets):
        """

        Args:
            command_result: result of var/log dump.
            ip_stat_cmd_dets: tunnel information obtained from execution of ipsec status command.

        Fucntion performs the following steps:
            1)for each tunnel, it's respective thread number is found from var/log dump.
            2)for that tunnel, using its thread, certain details are obtained from var/log dump
                ( initiator_spi, responders_spi, encryption_alg, integrity_alg )

        Returns: list containing dictionaries. Each dictionary contains all the required details of a tunnel.
            ( initiator_spi, responders_spi, encryption_alg, integrity_alg, Sk_ai, Sk_ar, Sk_ei, Sk_er )

        """
        tunnel_details = []
        for tunnel in ip_stat_cmd_dets:
            thread = self._get_ike_thread_nums_for_tunnel(tunnel, command_result)
            tunnel_details.append(self._get_complete_tunnel_details(thread, tunnel, command_result))
        logger.debug("Complete tunnel details :: \n{}".format(json.dumps(tunnel_details, indent=4, sort_keys=True)))
        return tunnel_details

    def _get_ike_thread_nums_for_tunnel(self, tunnel, command_result):
        """

        Args:
            tunnel: dictionary containing details of a tunnel
                    ( initiator_spi, responders_spi, encryption_alg, integrity_alg)
            command_result: contents of var/log dump

        Function performs the following step:
            1)Gets SPI search string by processing initiator_spi and responders_spi
            2)SPI search string is used to find the thread number. This thread number will be used to find rest of the
            details ie Secret keys of that tunnel.
        Returns: thread number for a particular tunnel.

        """
        spi_search_string = self._get_spi_search_string(tunnel.get("initiators_spi"), tunnel.get("responders_spi"))
        logger.debug("SPI string " + spi_search_string)
        return self._find_threads_from_var_log_output(spi_search_string, command_result)

    def _get_spi_search_string(self, init_spi, resp_spi):
        """
        Args:
            init_spi: initiators_spi value of a tunnel.
            resp_spi: responders_spi value of a tunnel.

        Function performs the following step:
            1)initiators spi string's characters are rearranged as a pair ie
            ABCDEFGHIJ..... => AB CD EF GH IJ....
            2)responders spi string's charcters are rearranged as a pair
            3)rearanged initiators spi and rearranged responders spi are concatenated(with a space character between
             them). This new string is used to search the thread number of it's respective tunnel.

        Returns: A string that will used to search thread number of a tunnel.
        """
        concatenated_init = [init_spi[index].upper() + init_spi[index + 1].upper() for index in
                             range(0, len(init_spi) - 1, 2)]
        concatenated_resp = [resp_spi[index].upper() + resp_spi[index + 1].upper() for index in
                             range(0, len(resp_spi) - 1, 2)]
        logger.debug(" ".join(concatenated_init) + " " + " ".join(concatenated_resp))
        return r"\d+\[IKE]\s+\d+:\s+{0}\s{1}".format(" ".join(concatenated_init), " ".join(
            concatenated_resp))

    def _find_threads_from_var_log_output(self, spi_search_string, command_result):
        """
        Args:
            spi_search_string: string that is used to find thread numbers of a tunnel.
            command_result:  var/log dump content.

        Function performs the following steps:
            1) Finds all the thread values that are associated with a particular tunnel.
            2) Find the exact thread which can later be used to find the secret keys.


        Returns: Thread number of a tunnel which can be later used to find secret keys of a tunnel.

        """
        thread_list = self._get_thread_values_from_command_result(spi_search_string, command_result)
        return self._get_exact_thread_containing_secret_keys(thread_list, command_result,
                                                             spi_search_string)

    def _get_thread_values_from_command_result(self, spi_search_string, command_result):
        """

        Args:
            spi_search_string: string that is used to find thread numbers of a tunnel.
            command_result: var/log dump content.

        Function performs the following steps:
            1) Use regular expression to find all the strings in var/log dump.
            2) extract thread number from the result strings and append it to a list.

        Returns: list of thread numbers of a tunnel.

        """
        thread_string_list, thread_value = re.findall(spi_search_string, command_result), []
        if thread_string_list:
            for thread in thread_string_list:
                thread_value.append(thread.split("[IKE]")[0].strip())
            return list(set(thread_value))
        else:
            BuiltIn().fail("Could not find thread number for {0}".format(spi_search_string))

    def _is_thread_containing_secret_keys(self, thread, command_result):
        """

        Args:
            thread: thread number belonging to a tunnel.
            command_result: var/log dump

        Function checks if secret keys exist for that thread number of a tunnel.

        Returns: Boolean True or False

        """
        sk_string_list = ["{0}[IKE] Sk_ai", "{0}[IKE] Sk_ar", "{0}[IKE] Sk_ei", "{0}[IKE] Sk_er"]
        for sk_string in sk_string_list:
            if sk_string.format(thread) not in command_result:
                return False
        else:
            logger.debug("exact thread " + thread)
            return True

    def _get_exact_thread_containing_secret_keys(self, thread_value, command_result,
                                                 spi_search_string):
        """
        Args:
            thread_value: list of thread numbers of a tunnel.
            command_result: var/log dump
            spi_search_string: string used to search thread numbers for a tunnel.

        Function verifies if thread number can be used to find secret keys. If found to be true
        then the respective thread is returned.

        Returns: thread value which can be used to find the secret keys.

        """
        for thread in thread_value:
            if self._is_thread_containing_secret_keys(thread, command_result):
                return thread
        else:
            BuiltIn().fail("No thread containing SK keys is present for {0}".format(
                spi_search_string))

    def _get_complete_tunnel_details(self, thread, tunnel, command_result):
        """

        Args:
            thread: thread which can be used to extract secret key details. (Sk_ai, Sk_ar, Sk_ei,
            Sk_er)
            tunnel: dictionary which contains basic details of the tunnel.
                    ( initiator_spi, responders_spi, encryption_alg, integity_alg)
            command_result: var/log dump content.

        Function performs the following tasks:
            1)extract all secret key details from the var/log dump using the obtained thread.
            2)create a dcitionary containg all the details of the tunnel.

        Returns: Dictionary containing all the details of a tunnel.
                ( initiator_spi, responders_spi, encryption_alg, integity_alg, Sk_ai, Sk_ar, Sk_ei,
                Sk_er )
        """
        secret_keys_list, tunnel_details = ["Sk_ai", "Sk_ar", "Sk_ei", "Sk_er"], dict(tunnel)
        pattern_string = [r"{0}\[IKE]\s+{1}.*\n.*\n*.*{0}\[IKE]\s+0:\s+([\s\w]+)\s\s."
                          r"*\n.*\n*.*charon:\s+{0}\[IKE\]\s+16:\s+([\s\w]+)\s",
                          r"{0}\[IKE]\s+{1}.*\n.*{0}\[IKE]\s+0:\s+([\s\w]+)\s\s.*"]
        for secret_key in secret_keys_list:
            for index, pattern in enumerate(pattern_string, 1):
                re_object = self._get_re_object_from_regx(pattern.format(thread, secret_key),
                                                          command_result)
                if re_object:
                    tunnel_details[secret_key.lower()] = self._get_details_from_regx_object(
                        re_object, index)
                    break
        return tunnel_details

    def _get_details_from_regx_object(self, re_object, index):
        """

        Args:
            re_object: RE object that contains secret key value.

        Returns: string containing secret key value.

        """
        if index == 1:
            str1, str2 = re_object.group(1), re_object.group(2)
            return "{0} {1}".format(str1, str2)
        else:
            return re_object.group(1)

    def _get_journal_output(self):
        """
        Function executes var/log cmd on bts and obtains the live dump.

        Returns: string which is a var/log dump.

        """
        charon_cat_cmd = "cat {} | grep -i charon".format(self.charon_logs_grep_op_file)
        result = self._get_output_from_command_execution(charon_cat_cmd, alias="bts")
        return result

    # ################################# validate_cmd_details_and_var_log #########################

    def _validate_cmd_details_and_var_log(self, ip_stat_cmd_dets, var_log_details):
        pass

    # ############################### add_var_log_details_to_ip_sec_v2_table ######################

    def _add_var_log_details_to_ip_sec_v2_table(self, var_log_details):
        """

        Args:
            var_log_details: list of dictionaries. Each dictionary has all the required details
            of a tunnel.

        Function performs the following steps:
            1) Obtain a string that contains all required details of a tunnel in a particular
                order.
            2)String obtained is appended to wiresharks ikev2 decryption table

        Returns:
        """
        file_obj = open("/home/ute/.wireshark/ikev2_decryption_table", "a+")
        for tunnel in var_log_details:
            ip_sec_table_str = self._get_ip_sec_table_string_to_be_added(tunnel)
            self._add_string_to_ip_sec_v2_table(ip_sec_table_str, file_obj)
        file_obj.close()

    def _get_ip_sec_table_string_to_be_added(self, tunnel):
        """

        Args:
            tunnel: dictionary containing all the details of a tunnel.

        Returns: string containing all the details of a tunnel in a particular order.

        """
        return "{0},{1},{2},{3},\"{4}\",{5},{6},\"{7}\"\n".format(
            tunnel["initiators_spi"], tunnel["responders_spi"],
            tunnel["sk_ei"].replace(" ", ""),
            tunnel["sk_er"].replace(" ", ""),
            tunnel["encryption_alg"],
            tunnel["sk_ai"].replace(" ", ""),
            tunnel["sk_ar"].replace(" ", ""),
            tunnel["integrity_alg"])

    def _add_string_to_ip_sec_v2_table(self, ip_sec_table_str, file_obj):
        """
        Args:
            ip_sec_table_str: string containing all the details of a tunnel in a particular order.

        Function to append the tunnel string to wireshark's ikev2 decryption table.

        Returns: None
        """

        logger.debug("Adding {} to wireshark table".format(ip_sec_table_str))
        file_obj.write(ip_sec_table_str)

    # ########################## command_execution_and_return_result ##############################

    def _set_remote_connection_with_host(self, host_details, alias):
        """

        Args:
            host_section: section in test line cofig json file containing the credential of a host.
            alias: execution context. used to refer to a particular session. Here it can be either
            'ipsec' or 'bts'

        Function to creates a ssh session with a host.

        Returns: None

        """
        ssh_client = paramiko.SSHClient()
        ssh_client.set_missing_host_key_policy(paramiko.AutoAddPolicy())
        ssh_client.connect(hostname=host_details["ip"], port=host_details.get("port", 22),
                           username=host_details["user"],
                           password=host_details["password"],
                           timeout=host_details.get("timeout", 120))
        if self.store.get(alias) is None:
            self.store[alias] = ssh_client

    def _get_output_from_command_execution(self, command, alias, wait_for_read=True):
        """

        Args:
            command: Command that is to be executed on a host.
            alias: Execution context.

        Function to execute a command on a host. Session must be created with the host to execute
        a command on it.

        Returns: Output of the command.

        """
        logger.debug("Executing command :: {}".format(str(command)))
        ssh_client = self.store.get(alias)
        std_in, std_out, std_err = ssh_client.exec_command(command=command)
        output = None
        if wait_for_read:
            self._verify_status_of_cmd_execution(command, std_out.channel.recv_exit_status(),
                                                 str(std_err.read()))
            output = decode_str(std_out.read())
            logger.debug("std out :: {}".format(output))
        return output

    def _verify_status_of_cmd_execution(self, command, status, output):
        """

        Args:
            command: Command that was executed on a host.
            status: status of command execution.
            output: output of the command.

        Function to verify command execution. Fails if command execution was improper.

        Returns: None

        """
        logger.info(output)
        if status != 0:
            BuiltIn().fail("{0} :: Execution failed \nStatus :: {1}\nOutput :: {2}".format(
                command, status, output))

    def _terminate_remote_connection_with_host(self, alias):
        """

        Args:
            alias: Execution context.

        Function to terminate ssh session with the host.

        Returns: None

        """
        ssh_client = self.store.get(alias)
        ssh_client.close()
